package com.mediconnect.external.drug;
import java.util.Map; import java.util.function.Supplier; import com.mediconnect.observability.BusinessMetrics; import com.mediconnect.prescription.domain.MedicationValidationStatus; import io.github.resilience4j.circuitbreaker.CircuitBreaker; import org.slf4j.*; import org.springframework.cache.annotation.Cacheable; import org.springframework.core.ParameterizedTypeReference; import org.springframework.stereotype.Service; import org.springframework.web.client.*;
@Service public class OpenFdaDrugValidationService { private static final Logger log=LoggerFactory.getLogger(OpenFdaDrugValidationService.class); private final RestClient openFdaRestClient; private final CircuitBreaker circuitBreaker; private final BusinessMetrics metrics; public OpenFdaDrugValidationService(RestClient openFdaRestClient,CircuitBreaker openFdaCircuitBreaker,BusinessMetrics metrics){this.openFdaRestClient=openFdaRestClient;this.circuitBreaker=openFdaCircuitBreaker;this.metrics=metrics;} @Cacheable(value="validatedDrugs",key="#drugName.toLowerCase()",unless="#result.validationStatus().name() == 'MANUAL_VALIDATION_REQUIRED'") public DrugValidationResult validate(String drugName){String normalized=drugName.trim();Supplier<DrugValidationResult> decorated=CircuitBreaker.decorateSupplier(circuitBreaker,()->queryOpenFda(normalized));try{return decorated.get();}catch(Exception ex){metrics.recordCircuitBreakerFallback();log.warn("OpenFDA validation unavailable for '{}'; manual pharmacy validation required. Cause: {}",normalized,ex.toString());return new DrugValidationResult(normalized,MedicationValidationStatus.MANUAL_VALIDATION_REQUIRED,"External pharmacology validation unavailable. Manual pharmacy validation is required.");}} private DrugValidationResult queryOpenFda(String drugName){try{Map<String,Object> response=openFdaRestClient.get().uri(uriBuilder->uriBuilder.path("/drug/label.json").queryParam("search","openfda.generic_name:\""+drugName+"\"").queryParam("limit",1).build()).retrieve().body(new ParameterizedTypeReference<>(){});boolean found=response!=null&&response.containsKey("results");if(found)return new DrugValidationResult(drugName,MedicationValidationStatus.VALIDATED,"Medication was found in OpenFDA labeling data.");return invalid(drugName);}catch(HttpClientErrorException.NotFound ex){return invalid(drugName);}} private DrugValidationResult invalid(String drugName){return new DrugValidationResult(drugName,MedicationValidationStatus.INVALID,"No matching medication labeling record was found in OpenFDA.");} }
